259	\begin{lemma}[Fact 4.20 in \cite{Natarajan2018NEEXP}]\label{fact:add-a-proj}
260		\lean{MIPStarRE.QPBT.opFamilyDistSq_mul_left_le}
261		\leanok
262		\uses{def:povm-distance}
263		Let $\mathcal A, \mathcal B, \mathcal C$ be finite sets, and let $\mu$ be a distribution over question pairs $(x,y)$. Let $\{A^x_{a,\,b}\}$ and $\{B^x_{a,\,b}\}$ be operators whose outcomes range over the product set $\mathcal A \times \mathcal B$. Suppose a set of operators $\{C^y_{a,\,c}\}$, whose outcomes range over the product set $\mathcal A \times \mathcal C$, satisfies the condition $\sum_c (C^y_{a,\,c})^\dagger C^y_{a,\,c} \le \Id$ for all $a$ and all $y$. If $A^x_{a,\,b} \approx_\delta B^x_{a,\,b}$ on average over $x$ sampled from the corresponding marginal of the distribution $\mu$, then $C^y_{a,\,c} A^x_{a,\,b} \approx_\delta C^y_{a,\,c} B^x_{a,\,b}$ on average over $(x,y)$ sampled from $\mu$.
264	\end{lemma}
265	\begin{proof}
266		Fix questions $x, y$ and answers $a \in \mathcal A$, $b \in \mathcal B$. Then
267		\begin{align*}
268			\sum_c \bigl\lVert (C^y_{a,\,c} A^x_{a,\,b} - C^y_{a,\,c} B^x_{a,\,b})\, \ket{\psi} \bigr\rVert^2
269			&= \bra{\psi} (A^x_{a,\,b} - B^x_{a,\,b})^\dagger \Bigl( \sum_c (C^y_{a,\,c})^\dagger C^y_{a,\,c} \Bigr) (A^x_{a,\,b} - B^x_{a,\,b}) \ket{\psi}\\
270			&\le \bigl\lVert (A^x_{a,\,b} - B^x_{a,\,b})\, \ket{\psi} \bigr\rVert^2\,,
271		\end{align*}
272		where the inequality uses the assumption $\sum_c (C^y_{a,\,c})^\dagger C^y_{a,\,c} \le \Id$. Summing over $a, b$ and averaging over $(x,y) \sim \mu$ yields the conclusion.
273	\end{proof}
