293	\begin{lemma}[Absorbing an approximating family into a projective sum]\label{lem:cool-closeness-fact}
294		\lean{MIPStarRE.QPBT.opDistSq_sum_sub_mul_le_of_projective}
295		\leanok
296		\uses{def:povm-distance, def:povm-conventions}
297		Let $\mathcal X$ and $\mathcal A$ be finite sets and $\mu$ a distribution on $\mathcal X$. Let $\{A^x_a\}_{a \in \mathcal A}$ be a projective measurement and let $\{B^x_a\}_{a \in \mathcal A}$ be a set of matrices. If $A^x_a \approx_\delta B^x_a$, then for all subsets $S \subseteq \mathcal A$ we have
298		\[
299			\sum_{a \in S} A^x_a \approx_\delta \sum_{a \in S} A^x_a \cdot B^x_a\,.
300		\]
301	\end{lemma}
302	\begin{proof}
303		By projectivity, $\sum_{a \in S} (A^x_a - A^x_a B^x_a) = \sum_{a \in S} A^x_a (A^x_a - B^x_a)$. Expanding the squared norm of the corresponding vector, the cross terms for distinct $a \ne a' \in S$ vanish because $A^x_a A^x_{a'} = 0$, so
304		\begin{align*}
305			\E_x \Bigl\lVert \sum_{a \in S} \bigl(A^x_a - A^x_a B^x_a\bigr) \ket{\psi} \Bigr\rVert^2
306			&= \E_x \sum_{a \in S} \bra{\psi} (A^x_a - B^x_a)^\dagger A^x_a (A^x_a - B^x_a) \ket{\psi}\\
307			&\le \E_x \sum_a \lVert (A^x_a - B^x_a)\ket{\psi} \rVert^2\,,
308		\end{align*}
309		% Under def:povm-distance the closeness hypothesis bounds the final quantity by
310		% O(delta), not by delta itself; the source
311		% (references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:364-380) elides this.
312		where the last step uses $A^x_a \le \Id$. All expectations are taken according to $\mu$, and the last quantity is $O(\delta)$ by the assumption $A^x_a \approx_\delta B^x_a$ (Definition~\ref{def:povm-distance}), which is the bound required for the conclusion.
313	\end{proof}
