353	The state-dependent distance is the right tool for reasoning about the closeness of measurement operators in a strategy. The following lemma converts joint consistency with a single projective measurement into an approximate commutation relation.
354	
355	\begin{lemma}[Approximate commutation from joint consistency]\label{lem:commutation-analysis}
356		\lean{MIPStarRE.QPBT.opDistSq_commutator_le}
357		\leanok
358		\uses{def:povm-distance, def:povm-conventions}
359		Let $\{A^x_{a,\,b}\}$, $\{B^x_{a,\,b,\,c}\}$, $\{C^x_{a,\,c}\}$ be POVMs. Suppose $\{B^x_{a,\,b,\,c}\}$ is projective, and
360		\begin{align*}
361			A^x_{a,\,b} \ot \Id_B &\approx_\delta \Id_A \ot B^x_{a,\,b}\,,\\
362			C^x_{a,\,c} \ot \Id_B &\approx_\delta \Id_A \ot B^x_{a,\,c}\,,
363		\end{align*}
364		where $B^x_{a,\,b} = \sum_c B^x_{a,\,b,\,c}$ and $B^x_{a,\,c} = \sum_b B^x_{a,\,b,\,c}$ are the marginals of Definition~\ref{def:povm-conventions}. Then the following approximate commutation relation holds:
365		\[
366			[A^x_{a,\,b},\, C^x_{a,\,c}] \ot \Id_B \approx_\delta 0\,.
367		\]
368	\end{lemma}
369	\begin{proof}
370		\uses{fact:add-a-proj, fact:triangle}
371		Applying Lemma~\ref{fact:add-a-proj} to $C^x_{a,\,c} \ot \Id_B \approx_\delta \Id_A \ot B^x_{a,\,c}$ with the multiplier family $\{A^x_{a,\,b} \ot \Id_B\}$, we have
372		\begin{equation}\label{eq:commutation-analysis-1}
373			A^x_{a,\,b}\, C^x_{a,\,c} \ot \Id_B \approx_\delta A^x_{a,\,b} \ot B^x_{a,\,c}\,.
374		\end{equation}
375		Similarly, applying Lemma~\ref{fact:add-a-proj} to $A^x_{a,\,b} \ot \Id_B \approx_\delta \Id_A \ot B^x_{a,\,b}$ with the multiplier family $\{\Id_A \ot B^x_{a,\,c}\}$, and using that $\{B^x_{a,\,b,\,c}\}$ is projective,
376		\begin{equation}\label{eq:commutation-analysis-2}
377			A^x_{a,\,b} \ot B^x_{a,\,c} \approx_\delta \Id_A \ot B^x_{a,\,c}\, B^x_{a,\,b} = \Id_A \ot B^x_{a,\,b,\,c}\,.
378		\end{equation}
379		Combining \eqref{eq:commutation-analysis-1} and \eqref{eq:commutation-analysis-2} via Lemma~\ref{fact:triangle},
380		\begin{equation}\label{eq:commutation-analysis-3}
381			A^x_{a,\,b}\, C^x_{a,\,c} \ot \Id_B \approx_\delta \Id_A \ot B^x_{a,\,b,\,c}\,.
382		\end{equation}
383		A symmetric argument gives
384		\begin{equation}\label{eq:commutation-analysis-4}
385			C^x_{a,\,c}\, A^x_{a,\,b} \ot \Id_B \approx_\delta \Id_A \ot B^x_{a,\,b,\,c}\,.
386		\end{equation}
387		The claim follows by subtracting \eqref{eq:commutation-analysis-3} and \eqref{eq:commutation-analysis-4}.
388	\end{proof}
